  return `
    <tr>
      <td style="padding: 8px; border: 1px solid #ccc;">${index + 1}</td>
      <td style="padding: 8px; border: 1px solid #ccc;">${item.name}</td>
      <td style="padding: 8px; border: 1px solid #ccc;">${item.quantity}</td>
      <td style="padding: 8px; border: 1px solid #ccc;">$${item.price.toFixed(2)}</td>
      <td style="padding: 8px; border: 1px solid #ccc;">$${subtotal.toFixed(2)}</td>
    </tr>
  `;
}).join('');

const html = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>Invoice ${order_id}</title>
</head>
<body style="font-family: Arial, sans-serif; color: #333; max-width: 700px; margin: auto; padding: 20px; border: 1px solid #ddd;">
  <h2 style="text-align: center;">Invoice</h2>
  <p><strong>Order ID:</strong> ${order_id}</p>
  <p><strong>Customer Name:</strong> ${customer_name}</p>
  <p><strong>Email:</strong> ${customer_email}</p>

  <table style="width: 100%; border-collapse: collapse; margin-top: 20px;">
    <thead>
      <tr>
        <th style="padding: 8px; border: 1px solid #ccc;">#</th>
        <th style="padding: 8px; border: 1px solid #ccc;">Product</th>
        <th style="padding: 8px; border: 1px solid #ccc;">Qty</th>
        <th style="padding: 8px; border: 1px solid #ccc;">Unit Price</th>
        <th style="padding: 8px; border: 1px solid #ccc;">Subtotal</th>
      </tr>
    </thead>
    <tbody>
      ${productRows}
    </tbody>
    <tfoot>
      <tr>
        <td colspan="4" style="text-align: right; padding: 8px; border: 1px solid #ccc;"><strong>Total:</strong></td>
        <td style="padding: 8px; border: 1px solid #ccc;"><strong>$${total.toFixed(2)}</strong></td>
      </tr>
    </tfoot>
  </table>

  <p style="margin-top: 40px; text-align: center;">Thank you for your order!</p>
</body>
</html>
`;

return [
  {
    json: {
      html
    }
  }
];
