**Daily Operations Overview:**
- **Daily Stock Check (9 AM)**: Automated trigger to monitor inventory levels
- **Fetch Stock Data**: Retrieves current medicine data from Google Sheets
- **Wait For All Data**: Ensures complete data retrieval before processing
- **Check Expiry Date and Low Stock**: Analyzes inventory for alerts
- **Update Google Sheet**: Records alert status and timestamps
- **Send Email Alert**: Notifies pharmacist of low stock and expiry issues

**Key Features:**
✅ Low stock threshold monitoring
✅ Expiry date tracking (30-day advance warning)
✅ Automated email notifications
✅ Google Sheets integration for easy management"}, "typeVersion": 1}, {"id": "e062c1ab-c264-4eaa-9a9f-91354cc2bd30", "name": "Wait For All Data", "type": "n8n-nodes-base.wait", "position": [-560, 440], "webhookId": "ff6fa958-553d-4dd6-816d-d69ed73a49fd", "parameters": {}, "typeVersion": 1.1}, {"id": "10f4705c-3f93-4190-bb9b-86151ee49834", "name": "Check Expiry Date and Low Stock", "type": "n8n-nodes-base.code", "position": [-340, 440], "parameters": {"jsCode": "// Get all input items from Google Sheets
const items = $input.all();
const alerts = [];
const lowStockItems = [];
const expiryItems = [];

for (const item of items) {
  const data = item.json;

  // Skip header row or empty entries
  if (!data.medicine_name || data.medicine_name === 'medicine_name') {
    continue;
  }

  // Stock threshold (default 10 units if not specified)
  const threshold = data.threshold || 10;

  // Expiry warning in days (30 days before expiry)
  const expiryWarningDays = 30;

  // Check Low Stock
  if (data.stock_quantity && parseInt(data.stock_quantity) <= threshold) {
    const lowStockAlert = {
      medicine_name: data.medicine_name,
      stock_quantity: data.stock_quantity,
      threshold: threshold,
      type: "Low Stock",
      alert_message: `LOW STOCK: ${data.medicine_name} has only ${data.stock_quantity} units remaining (threshold: ${threshold})`
    };

    alerts.push(lowStockAlert);
    lowStockItems.push(`• ${data.medicine_name}: ${data.stock_quantity} units (threshold: ${threshold})`);
  }

  // Check Expiry Date
  if (data.expiry_date) {
    const today = new Date();
    const expiryDate = new Date(data.expiry_date);
    const daysLeft = Math.ceil((expiryDate - today) / (1000 * 60 * 60 * 24));

    if (daysLeft <= expiryWarningDays) {
      const expiryAlert = {
        medicine_name: data.medicine_name,
        expiry_date: data.expiry_date,
        days_left: daysLeft,
        type: daysLeft > 0 ? "Near Expiry" : "Expired",
        alert_message: daysLeft > 0
          ? `NEAR EXPIRY: ${data.medicine_name} expires in ${daysLeft} days (${data.expiry_date})`
          : `EXPIRED: ${data.medicine_name} expired ${Math.abs(daysLeft)} days ago (${data.expiry_date})`
      };

      alerts.push(expiryAlert);
      expiryItems.push(daysLeft > 0 
        ? `• ${data.medicine_name}: Expires in ${daysLeft} days (${data.expiry_date})`
        : `• ${data.medicine_name}: EXPIRED ${Math.abs(daysLeft)} days ago (${data.expiry_date})`);
    }
  }
}

// Create summary for email
const emailSummary = {
  lowStockList: lowStockItems.length > 0 ? lowStockItems.join('\n') : 'No low stock items found.',
  expiryList: expiryItems.length > 0 ? expiryItems.join('\n') : 'No items near expiry or expired.',
  totalAlerts: alerts.length,
  timestamp: new Date().toISOString()
};

// Return all alerts with email summary
if (alerts.length > 0) {
  return [{ json: emailSummary }, ...alerts.map(alert => ({ json: alert }))];
} else {
  // Return empty summary if no alerts
  return [{ json: emailSummary }];
}"}, "typeVersion": 2}], "active": false, "pinData": {}, "settings": {"executionOrder": "v1"}, "versionId": "89c25bc6-c09d-433d-85ff-88f9baad4581", "connections": {"Fetch Stock Data": {"main": [[{"node": "Wait For All Data", "type": "main", "index": 0}]]}, "Daily Stock Check": {"main": [[{"node": "Fetch Stock Data", "type": "main", "index": 0}]]}, "Wait For All Data": {"main": [[{"node": "Check Expiry Date and Low Stock", "type": "main", "index": 0}]]}, "Update Google Sheet": {"main": [[{"node": "Send Email Alert", "type": "main", "index": 0}]]}, "Check Expiry Date and Low Stock": {"main": [[{"node": "Update Google Sheet", "type": "main", "index": 0}]]}}}

